<div id="page-content" class="page-wrapper clearfix">
<div class="card"><div class="page-title clearfix"><div><h1><?php echo esc($checklist->name); ?> <small class="text-muted">v<?php echo (int)$checklist->version; ?></small></h1><p class="text-muted mb0"><?php echo esc($checklist->description); ?></p></div><div class="title-button-group"><a class="btn btn-default" href="<?php echo get_uri('engenharia/checklists'); ?>"><?php echo app_lang('back'); ?></a> <a class="btn btn-default" href="<?php echo get_uri('engenharia/checklists/preview/' . $checklist->id); ?>"><i data-feather="eye" class="icon-16"></i> <?php echo app_lang('view'); ?></a> <button class="btn btn-default engenharia-new-version" data-id="<?php echo $checklist->id; ?>"><i data-feather="git-branch" class="icon-16"></i> <?php echo app_lang('engenharia_new_version'); ?></button> <?php echo modal_anchor(get_uri('engenharia/checklists/group_modal_form/' . $checklist->id), "<i data-feather='plus' class='icon-16'></i> " . app_lang('engenharia_add_group'), array('class'=>'btn btn-primary')); ?></div></div>
<div class="card-body"><div class="alert alert-info"><?php echo $checklist->status === 'published' || !empty($checklist->is_enabled) ? app_lang('engenharia_checklist_version_protected') : app_lang('engenharia_checklist_draft_editable'); ?></div>
<?php if($groups){foreach($groups as $group){ ?><div class="card mb15"><div class="card-header clearfix"><strong><?php echo esc($group->title); ?></strong><span class="float-end"><a class="btn btn-default btn-sm" href="#" onclick="return engenhariaSort(event,'group',<?php echo $group->id; ?>,-1,<?php echo $checklist->id; ?>);">↑</a> <a class="btn btn-default btn-sm" href="#" onclick="return engenhariaSort(event,'group',<?php echo $group->id; ?>,1,<?php echo $checklist->id; ?>);">↓</a> <?php echo modal_anchor(get_uri('engenharia/checklists/item_modal_form/' . $checklist->id), "<i data-feather='plus' class='icon-14'></i> " . app_lang('engenharia_add_item'), array('class'=>'btn btn-primary btn-sm','data-post-group_id'=>$group->id)); ?></span></div><div class="card-body"><p class="text-muted"><?php echo esc($group->description); ?></p><div class="table-responsive"><table class="table table-sm"><thead><tr><th><?php echo app_lang('code'); ?></th><th><?php echo app_lang('title'); ?></th><th><?php echo app_lang('engenharia_response_type'); ?></th><th><?php echo app_lang('engenharia_criticality'); ?></th><th><?php echo app_lang('engenharia_order'); ?></th><th></th></tr></thead><tbody><?php foreach($items as $item){if((int)$item->group_id !== (int)$group->id)continue; ?><tr><td><?php echo esc($item->code); ?></td><td><?php echo esc($item->title); ?><br><small><?php echo esc($item->question); ?></small></td><td><?php echo esc($item->response_type); ?></td><td><?php echo esc($item->criticality); ?></td><td><?php echo (int)$item->sort; ?> <a href="#" onclick="return engenhariaSort(event,'item',<?php echo $item->id; ?>,-1,<?php echo $checklist->id; ?>);">↑</a> <a href="#" onclick="return engenhariaSort(event,'item',<?php echo $item->id; ?>,1,<?php echo $checklist->id; ?>);">↓</a></td><td><?php echo modal_anchor(get_uri('engenharia/checklists/item_modal_form/' . $checklist->id . '/' . $item->id), "<i data-feather='edit' class='icon-14'></i>", array('class'=>'btn btn-default btn-sm')); ?></td></tr><?php } ?></tbody></table></div></div></div><?php }}else{ ?><p class="text-muted"><?php echo app_lang('engenharia_no_groups'); ?></p><?php } ?></div></div></div>
<script>$(function(){$('.engenharia-new-version').on('click',function(){if(!confirm('<?php echo app_lang('engenharia_confirm_version'); ?>'))return;$.post('<?php echo_uri('engenharia/checklists/version'); ?>',{id:$(this).data('id')},function(r){if(r.success)window.location.href='<?php echo get_uri('engenharia/checklists/manage/'); ?>'+r.id;else appAlert.error(r.message);},'json');});});function engenhariaSort(e,type,id,delta,checklist){e.preventDefault();$.post('<?php echo_uri('engenharia/checklists/sort'); ?>',{type:type,id:id,delta:delta,checklist_id:checklist},function(r){if(r.success)location.reload();else appAlert.error(r.message);},'json');return false;}</script>
